</div>"}, {"fieldtype": "Section Break", "label": "", "options": ""}, {"fieldtype": "Column Break", "options": ""}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "<!-- Force override any inline widths coming from the terms database -->
