<!-- 1. Logic: Discount Calculation -->
{% set ns = namespace(total_discount=0.0) %}
{% for item in doc.items %}
    {% set ns.total_discount = ns.total_discount + (item.discount_amount | float or 0) %}
{% endfor %}

<div class="summary-area" style="border-top:1.5px solid #000; font-family: Arial, sans-serif;">

